#!/usr/bin/env bash
# Question 1: Unhealthy Deployment storefront. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "retail" >/dev/null 2>&1 || kubectl get namespace "retail" >/dev/null
timeout 60 bash -c "until kubectl -n 'retail' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: v1
kind: ConfigMap
metadata:
  name: storefront-config
  namespace: retail
data:
  mode: production
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: storefront
  namespace: retail
  labels: { app: storefront }
spec:
  replicas: 0
  selector:
    matchLabels: { app: storefront }
  template:
    metadata:
      labels: { app: storefront }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          resources:
            requests: { cpu: 50m, memory: 32Mi }
            limits: { cpu: 250m, memory: 128Mi }
          readinessProbe:
            httpGet: { path: /, port: 80 }
            periodSeconds: 5
          livenessProbe:
            tcpSocket: { port: 80 }
            periodSeconds: 5
            failureThreshold: 2
          env:
            - name: APP_MODE
              valueFrom:
                configMapKeyRef: { name: storefront-config, key: mode }
EOF
kubectl -n "retail" get deployment "storefront" -o jsonpath='{.metadata.uid}' > "/var/tmp/cka-q1.uid"
chmod 644 "/var/tmp/cka-q1.uid"

(
case "${Q1_FAULT}" in
  oom-killed)
    kubectl -n "retail" set resources "deployment/storefront" --requests=memory=4Mi --limits=memory=4Mi
    ;;
  image-pull)
    kubectl -n "retail" set image "deployment/storefront" web=nginx:1.27-alpne
    ;;
  bad-command)
    kubectl -n "retail" patch deployment "storefront" --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"web","command":["nginx","-g","daemon off; worker_procs 2;"]}]}}}}'
    ;;
  busybox-bash)
    kubectl -n "retail" patch deployment "storefront" --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"web","command":["/bin/bash","-c","nginx -g daemon off;"]}]}}}}'
    ;;
  configmap-key)
    kubectl -n "retail" patch configmap "storefront-config" --type=json -p '[{"op":"move","from":"/data/mode","path":"/data/mod"}]'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
case "${Q1_FAULT_2}" in
  liveness-port)
    kubectl -n "retail" patch deployment "storefront" --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"web","livenessProbe":{"tcpSocket":{"port":8080}}}]}}}}'
    ;;
  readiness-path)
    kubectl -n "retail" patch deployment "storefront" --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"web","readinessProbe":{"httpGet":{"path":"/healthz"}}}]}}}}'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
case "${Q1_FAULT_3}" in
  requests-too-large)
    kubectl -n "retail" set resources "deployment/storefront" --requests=cpu=64 --limits=cpu=64
    ;;
  node-selector)
    kubectl -n "retail" patch deployment "storefront" --type=strategic -p '{"spec":{"template":{"spec":{"nodeSelector":{"disktype":"ssd"}}}}}'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
kubectl -n "retail" scale "deployment/storefront" --replicas=2
notready=0
for _ in $(seq 1 10); do
  states="$(kubectl -n "retail" get pods -l "app=storefront" -o jsonpath='{range .items[*]}{.status.phase} {.status.conditions[?(@.type=="Ready")].status} {.status.conditions[?(@.type=="PodScheduled")].status} {.status.containerStatuses[0].state.waiting.reason} {.status.containerStatuses[0].restartCount}{"\n"}{end}' 2>/dev/null)"
  if grep -qE '(ErrImagePull|ImagePullBackOff|CrashLoopBackOff|CreateContainerConfigError|CreateContainerError|RunContainerError)|[1-9][0-9]*$|^[A-Za-z]+ [A-Za-z]* False' <<< "$states"; then break; fi
  if kubectl -n "retail" get events --field-selector reason=FailedMount -o name 2>/dev/null | grep -q .; then break; fi
  if grep -qE '^Running False' <<< "$states"; then
    notready=$((notready + 1))
    (( notready >= 3 )) && break
  else
    notready=0
  fi
  sleep 2
done
)
